SELECT tenant_id,id,'Implementation services',1,amount,amount FROM invoices ON CONFLICT DO NOTHING;
SELECT tenant_id,id,(SELECT u.id FROM users u WHERE u.tenant_id=p.tenant_id LIMIT 1),'owner' FROM projects p ON CONFLICT DO NOTHING;
VALUES('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','member') ON CONFLICT DO NOTHING;
